UPDATE INT_SERVERFUNCTION SET NAME = COALESCE(NULL, NAME), DESCRIPTION = COALESCE(NULL, DESCRIPTION), TYPE = COALESCE(NULL, TYPE), JDBC_ID = NULL, CODE = COALESCE('SELECT COUNT(*) AS TOTAL FROM COLABORADOR c WHERE (''{{crId}}'' = '''' OR c.CR_ID = ''{{crId}}'')
  AND (''{{busca}}'' = '''' OR c.NOME LIKE ''%{{busca}}%'' OR c.CARGO LIKE ''%{{busca}}%'')', CODE), PUBLIC_EXECUTION = COALESCE(NULL, PUBLIC_EXECUTION), CRON_EXPRESSION = NULL, CRON_INPUT_JSON = NULL WHERE NAME = 'colaboradoresCount';
